package vn.edu.fpt.seal.modules.chat.service; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.edu.fpt.seal.common.exception.ApiException; import vn.edu.fpt.seal.modules.chat.dto.*; import vn.edu.fpt.seal.modules.chat.entity.TeamChatMessage; import vn.edu.fpt.seal.modules.chat.repository.TeamChatMessageRepository; import vn.edu.fpt.seal.modules.team.repository.TeamRepository; import vn.edu.fpt.seal.modules.team.repository.TeamMemberRepository; import vn.edu.fpt.seal.modules.user.repository.UserRepository; import java.util.*; @Service @RequiredArgsConstructor public class TeamChatService{private final TeamChatMessageRepository repo; private final TeamRepository teamRepo; private final TeamMemberRepository teamMemberRepo; private final UserRepository userRepo; @Transactional(readOnly=true) public List<TeamChatMessageResponse> list(UUID teamId){return repo.findTop100ByTeamIdOrderByCreatedAtAsc(teamId).stream().map(this::map).toList();} @Transactional public TeamChatMessageResponse create(CreateTeamChatMessageRequest r,UUID senderId){var team=teamRepo.findById(r.teamId()).orElseThrow(()->ApiException.notFound("Team not found")); if(!teamMemberRepo.existsByTeamIdAndUserId(team.getId(),senderId)) throw ApiException.forbidden("Only team members can post team chat messages"); var sender=userRepo.findById(senderId).orElseThrow(()->ApiException.notFound("Sender not found")); return map(repo.save(TeamChatMessage.builder().team(team).sender(sender).message(r.message().trim()).build()));} private TeamChatMessageResponse map(TeamChatMessage m){var s=m.getSender(); return new TeamChatMessageResponse(m.getId(),m.getTeam().getId(),s.getId(),s.getFullName(),s.getEmail(),m.getMessage(),m.getCreatedAt());}}
